  a=event(state(),'drive_list');b=event(event(a['state'],'cancel')['state'],'drive_list');i={k:a['effect'][k]for k in ['purpose','drive_ticket']};i.update(error='Old failure',sent=False);unchanged('old failure cannot clear a newer busy request',b,event(b['state'],'failure',i));i={k:b['effect'][k]for k in ['purpose','drive_ticket']};i.update(error='Current controlled failure',sent=False);failed=event(b['state'],'failure',i);check('current failure settles its own request',not failed['state']['busy']and 'Current controlled failure'in failed['state']['notice'])
