  # Saved snapshots retain their original connection and require their own phase owner.
  a=event(state(),'save_drive');st=event(a['state'],'cancel')['state'];st=event(st,'remote_save_discard')['state'];b=event(st,'save_drive');unchanged('cancelled snapshot acknowledgement cannot advance a newer snapshot',b,response(b,status=201,source=a));d=response(b,status=201);check('current snapshot acknowledgement waits for owned verification',d['effect']['purpose']=='saved_verify');content=d['state']['remote_save']['content'];d=response(d,content);check('snapshot saved success requires exact current readback',d['state'].get('remote_save')is None and 'exact bytes verified'in d['state']['notice'])
